function parseModelJson(raw) {
  const cleaned = String(raw || '').replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();
  try { return JSON.parse(cleaned); } catch (_) { return null; }
}
return $input.all().map(({json:e}) => {
  const rawClaude = e.merged_response ||
    (Array.isArray(e.content) ? e.content.filter(b => b && b.type === 'text').map(b => b.text || '').join('\n').trim() : '') ||
    e.text || e.output_text || '';
  const draft = parseModelJson(rawClaude);
  const proofUrl = String(draft?.url_preuve || '').trim();
  const hasProofUrl = /^https?:\/\//i.test(proofUrl);
  const validDraft = !!(draft && draft.validation_status === 'BROUILLON_A_VALIDER' &&
    draft.entreprise_identifiee && draft.objet && draft.corps && draft.fait_reference && hasProofUrl);
  const noSend = !validDraft;

  const enterpriseName = draft?.entreprise_identifiee || e.titre || 'Inconnu';

  return { json: {
    entreprise_identifiee: enterpriseName,
    niveau_priorite_heuristique: e.niveau_priorite || e.priorite_heuristique || 'B',
    score_heuristique_sur_100: e.score_heuristique || 50,
    url_source_initiale: e.url_source_initiale || e.url_source || '',
    titre_source_initiale: e.titre_source || e.titre || '',
    extrait_source_initiale: e.extrait_moteur || e.extrait || '',
    statut_scraping: e.statut_scraping || 'CONTENU_RECUPERE',
    url_page_scrapee: e.url_page_scrapee || '',
    date_detectee_par_le_scraper: e.date_detectee || e.date_publication || null,
    analyse_web_perplexity: e.analyse_perplexity || null,
    citations_perplexity: e.sources_citees_perplexity || [],
    statut_brouillon: noSend ? 'NE_PAS_ENVOYER_OU_REVOIR' : 'BROUILLON_A_VALIDER_PAR_UN_HUMAIN',
    objet_email: noSend ? '' : draft.objet,
    corps_email: noSend ? '' : draft.corps,
    fait_reference: draft?.fait_reference || '',
    url_preuve_principale: noSend ? '' : proofUrl,
    justification_personnalisation: draft?.justification_personnalisation || '',
    points_a_verifier: draft?.points_a_verifier || ['Vérifier la source et l’identité de l’entreprise avant toute prise de contact.'],
    date_traitement: new Date().toISOString(),
    // Clé unique pour le suivi et l'anti-doublon e-mail
    id_unique_alerte: `${enterpriseName.toLowerCase().replace(/[^a-z0-9]/g, '_')}_${e. niveau_priorite || 'B'}`,
    email_envoye: false,
    destinataire_email: "kezynganou@gmail.com",
    note: 'Prototype de veille B2B : aucun envoi automatique. Le score est heuristique et toute donnée doit être vérifiée.'
  } };
});

function clean(s) { return String(s || '').replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim(); }
return $input.all().map(({json:e}) => {
  const researchRaw = clean(e.output_text || e.text || e.choices?.[0]?.message?.content || e.response?.output_text || '');
  const citations = Array.isArray(e.citations) ? e.citations : [];
  const facts = {
    titre_source: e.titre,
    extrait_moteur: e.extrait,
    url_source_initiale: e.url_source,
    date_detectee: e.date_publication,
    contenu_page_scrape: String(e.texte_page_scrape || '').slice(0,2500),
    score_heuristique: e.score_heuristique,
    priorite_heuristique: e.niveau_priorite,
    mots_cles_detectes: [...(e.mots_cles_secteur || []), ...(e.mots_cles_signal || []), ...(e.mots_cles_activite || [])],
    analyse_perplexity_brute: researchRaw,
    citations_perplexity: citations
  };
  const prompt = `RÔLE
Tu es un rédacteur commercial B2B senior préparant des brouillons pour DV GROUP. Les domaines pertinents sont l'automatisme, la maintenance industrielle et l'ingénierie.

OBJECTIF
Préparer un email bref, crédible, naturel et personnalisé, uniquement si le signal commercial est suffisamment vérifié.

DONNÉES ET ANALYSE
${JSON.stringify(facts, null, 2)}

RÈGLES STRICTES
- N'invente aucun nom d'entreprise, contact, chiffre, projet, besoin ou coordonnée.
- Le score heuristique n'est jamais une preuve factuelle.
- Le signal doit être confirmé par l'analyse Perplexity et accompagné d'une URL source vérifiable.
- N'affirme pas que l'entreprise a besoin des services de DV GROUP ; formule une hypothèse mesurée.
- N'inclus pas d'adresse email inventée et n'envoie aucun message.
- Si le statut est NON_CONFIRME ou INCERTAIN, ou si l'entreprise, le signal confirmé ou l'URL de preuve manque, retourne validation_status = NE_PAS_ENVOYER et laisse objet et corps vides.
- Sinon, retourne validation_status = BROUILLON_A_VALIDER.
- Style : français professionnel, naturel, précis et poli ; aucune flatterie artificielle ni promesse excessive. Maximum 120 mots pour le corps.
- Propose un échange de 15 minutes sans imposer de créneau.

FORMAT
Réponds uniquement en JSON valide avec les clés : entreprise_identifiee, validation_status, objet, corps, fait_reference, url_preuve, justification_personnalisation, points_a_verifier.`;
  return { json: { ...e, analyse_perplexity: researchRaw, sources_citees_perplexity: citations, prompt_claude: prompt } };
});

// Prépare une recherche web de vérification pour chaque résultat retenu.
return $input.all().map(({json:r}) => {
  const researchQuestion = `Tu es analyste de prospection B2B pour DV GROUP, intéressé par l'automatisme, la maintenance industrielle et l'ingénierie.

Vérifie le signal d'affaires et l'identité de l'entreprise avec une recherche web à jour. Le titre initial ne suffit pas à prouver qu'il s'agit d'un prospect.

Titre : ${r.titre}
Extrait : ${r.extrait}
URL initiale : ${r.url_source}
Date détectée : ${r.date_publication || 'non indiquée'}
Contenu de la page (peut être vide) :
${String(r.texte_page_scrape || '').slice(0,6500)}

Recherche le site officiel et/ou une source d'actualité fiable. Sépare les faits vérifiés des hypothèses. N'invente aucune entreprise, date, statistique ou besoin. Si le signal ne peut pas être confirmé, indique-le.

CONSIGNE STRICTE POUR LE NOM :
Pour la clé \`entreprise_identifiee\`, donne UNIQUEMENT le nom légal officiel et court de l'entreprise (ex: "Cover RH" ou "Cover RH SARL"). Interdiction formelle de rédiger une phrase, une description ou une explication dans cette clé.

Réponds en français et en JSON valide avec les clés : entreprise_identifiee, site_officiel, signal_verifie, resume_factuel, date_signal, url_preuve_principale, autres_sources (tableau d'URL), niveau_confiance (faible/moyen/élevé), pertinence_dv_group (faible/moyenne/élevée), statut (CONFIRME/INCERTAIN/NON_CONFIRME), justification.`;
  return { json: { ...r, question_perplexity: researchQuestion } };
});

// Reassocie le résultat Web Fetch avec les pages sélectionnées, même si certaines ne répondent pas.
const selected = $('6 · Sélectionner au maximum 8 pages').all().map(i => i.json);
const crawled = $input.all().map(i => i.json);
function canonical(value) {
  try { const u = new URL(String(value || '')); return (u.origin + u.pathname).replace(/\/$/,'').toLowerCase(); }
  catch (_) { return ''; }
}
const byUrl = new Map();
for (const page of crawled) {
  const u = page.url || page.loadedUrl || page.crawlUrl || page.canonicalUrl || page.request?.url || page.originalUrl || '';
  const key = canonical(u);
  if (key) byUrl.set(key, page);
}
return selected.map(r => {
  const page = byUrl.get(canonical(r.url_source)) || null;
  const rawText = page ? (
    page.markdown || page.text || page.content || page.html || page.body ||
    page.result?.markdown || page.result?.text || page.data?.markdown || page.data?.text ||
    page.websiteContent?.text || page.websiteContent?.markdown || ''
  ) : '';
  return { json: {
    ...r,
    texte_page_scrape: String(rawText || '').slice(0, 9000),
    url_page_scrapee: page ? (page.url || page.loadedUrl || page.canonicalUrl || r.url_source) : null,
    statut_scraping: rawText ? 'CONTENU_RECUPERE' : 'CONTENU_NON_RECUPERE_A_VERIFIER',
    nombre_pages_retournees_par_crawler: crawled.length
  } };
});

// Sélectionne au maximum 8 pages puis produit un item n8n par URL pour Web Fetch.
const rows = $input.all().map(i => i.json)
  .filter(r => r.url_source && /^https?:\/\//i.test(r.url_source) && r.score_heuristique >= 40 && ['A','B','C'].includes(r.niveau_priorite))
  .sort((a,b) => b.score_heuristique - a.score_heuristique)
  .slice(0, 8);
return rows.map(r => ({
  json: {
    ...r,
    url: r.url_source,
    note_crawl: 'Une seule page est récupérée pour cette URL ; pas de crawl des sous-pages.'
  }
}));

const rows = $input.all().map(i => i.json);
const count = tier => rows.filter(r => r.niveau_priorite === tier).length;
const qualifies = rows.filter(r => ['A','B'].includes(r.niveau_priorite));
return [{ json: {
  type_rapport: 'KPI de veille web — résultats à vérifier',
  date_execution_utc: new Date().toISOString(),
  resultats_uniques_collectes: rows.length,
  priorite_A: count('A'), priorite_B: count('B'), priorite_C: count('C'), hors_cible: count('Hors cible'),
  resultats_A_B: qualifies.length,
  taux_A_B_pct: rows.length ? Math.round(100 * qualifies.length / rows.length) : 0,
  sources_A_B: qualifies.slice(0,20).map(r => ({ titre:r.titre, score:r.score_heuristique, priorite:r.niveau_priorite, url:r.url_source })),
  rappel: 'Le score est heuristique ; il ne prouve ni l’existence d’un besoin ni l’adéquation commerciale. Vérifier les sources.'
} }];

// Qualification heuristique et explicable à partir des titres/extraits ; elle ne remplace pas la vérification humaine.
function norm(s) { return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,''); }
const secteurs = ['industrie','industriel','industrielle','usine','manufactur','production','mecanique','metallurgie','aeronautique','automobile','energie','agroalimentaire','logistique','automatisme','robotique','maintenance','equipementier','atelier'];
const signaux = ['investissement','investit','investir','nouveau site','nouvelle usine','extension','modernisation','recrutement','recrute','embauche','nouvelle ligne','ligne de production','augmentation de capacite','acquisition','construction','developpe','lance un projet','plan industriel','agrandissement','nouveau contrat'];
const activites = ['maintenance','automatisme','robotique','ligne de production','controle industriel','ingenierie','fiabilite','usinage','moteur','pneumatique','hydraulique','capteur','automatisation','process industriel'];
return $input.all().map(({json:r}) => {
  const corpus = norm(`${r.titre || ''} ${r.extrait || ''} ${r.domaine_source || ''}`);
  const hitsSecteur = secteurs.filter(k => corpus.includes(k));
  const hitsSignal = signaux.filter(k => corpus.includes(k));
  const hitsActivite = activites.filter(k => corpus.includes(k));
  let score = 0; const raisons = [];
  if (hitsSecteur.length) { score += 30; raisons.push('Pertinence industrielle détectée (+30)'); }
  if (hitsSignal.length) { score += 30; raisons.push('Signal commercial potentiel dans le titre/extrait (+30)'); }
  if (hitsActivite.length) { score += 20; raisons.push('Lien potentiel avec maintenance/automatisme/ingénierie (+20)'); }
  if (r.url_source) { score += 10; raisons.push('URL source disponible pour contrôle (+10)'); }
  if (r.date_publication) { score += 10; raisons.push('Date de publication détectée (+10)'); }
  score = Math.min(100, score);
  const tier = score >= 70 ? 'A' : score >= 50 ? 'B' : score >= 30 ? 'C' : 'Hors cible';
  const actions = {
    'A':'Vérifier le signal et l’entreprise ; priorité de recherche élevée',
    'B':'Vérifier le signal ; étudier une prise de contact si le besoin est confirmé',
    'C':'Conserver en veille ; vérifier la pertinence avant toute action',
    'Hors cible':'Ne pas prioriser sans nouvel élément pertinent'
  };
  return { json: { ...r, score_heuristique: score, niveau_priorite: tier, mots_cles_secteur: hitsSecteur, mots_cles_signal: hitsSignal, mots_cles_activite: hitsActivite, raisons_score: raisons, action_recommandee: actions[tier], verification_humaine_obligatoire: true, envoi_automatique: false } };
});

const candidates = [];

for (const item of $input.all()) {
  const data = item.json;

  // Recherche des résultats dans toutes les variations possibles de clés Apify
  const results = data.organicResults || data.organic_results || data.results || data.items || [];

  if (Array.isArray(results) && results.length > 0) {
    for (const r of results) {
      candidates.push({
        titre: r.title || r.name || 'Sans titre',
        extrait: r.description || r.snippet || '',
        url_source: r.url || r.link || '',
        url_canonique: r.url || r.link || '',
        domaine_source: r.domain || '',
        date_publication: r.date || null,
        requete_source: data.searchQuery?.term || '',
        position_google: r.position || null
      });
    }
  } else {
    // Fallback si la structure est un objet plat unique
    candidates.push({
      titre: data.title || 'Résultat brut',
      extrait: data.description || data.snippet || JSON.stringify(data).slice(0, 200),
      url_source: data.url || 'https://usinenouvelle.com',
      url_canonique: data.url || 'https://usinenouvelle.com',
      domaine_source: 'usinenouvelle.com',
      date_publication: null,
      requete_source: 'Recherche web',
      position_google: 1
    });
  }
}

return candidates.map((r, idx) => ({ 
  json: { 
    ...r, 
    id_resultat: idx + 1, 
    statut_source: 'Résultat de recherche à vérifier' 
  } 
}));

// Veille B2B de démonstration : signaux industriels publics en France.
// Une requête par ligne pour Google Search Scraper.
const queries = [
  'industrie France investissement usine 2026',
  'entreprise industrielle France modernisation ligne de production 2026',
  'industrie France recrutement maintenance automatisme robotique 2026',
  'site:usinenouvelle.com industrie France investissement usine modernisation 2026'
].join('\n');
return [{ json: {
  queries,
  pays_cible: 'France',
  objectif: 'Détecter des signaux industriels publics potentiellement pertinents pour la maintenance, l’automatisme et l’ingénierie',
  limite_recherche_approfondie: 8,
  note: 'Démonstration de veille B2B. Vérification des sources obligatoire avant toute prise de contact.'
} }];

// 1. Récupère les prospects entrants de ton flux principal
const currentItems = $input.all();

// 2. Récupère l'historique existant depuis Google Sheets de manière sécurisée
let existingUrls = [];
try {
  const sheetRows = $('Get row(s) in sheet').all();
  if (sheetRows && sheetRows.length > 0) {
    existingUrls = sheetRows
      .map(row => row.json['URL Source'] || row.json['url_source_initiale'])
      .filter(Boolean);
  }
} catch (e) {
  existingUrls = [];
}

// 3. Filtrage des prospects : on ne garde que les nouveautés
const uniqueNewItems = [];
const seenUrlsInCurrentBatch = new Set();

for (const item of currentItems) {
  const json = item.json;
  const urlSource = json.url_source_initiale;

  if (!urlSource) continue;

  const isAlreadyInSheet = existingUrls.includes(urlSource);
  const isDuplicateInBatch = seenUrlsInCurrentBatch.has(urlSource);

  if (!isAlreadyInSheet && !isDuplicateInBatch) {
    seenUrlsInCurrentBatch.add(urlSource);

    uniqueNewItems.push({
      json: {
        Enterprise: json.entreprise_identifiee || 'Inconnu',
        Priorite: json.niveau_priorite_heuristique || 'B',
        Score: json.score_heuristique_sur_100 || 50,
        Date: json.date_traitement || new Date().toISOString(),
        "URL Source": urlSource,
        Description: json.analyse_web_perplexity || json.extrait_source_initiale || '',
        objet_email: json.objet_email || '',
        corps_email: json.corps_email || '',
        niveau_priorite_heuristique: json.niveau_priorite_heuristique || 'B',
        id_unique_alerte: json.id_unique_alerte || ''
      }
    });
  }
}

return uniqueNewItems;
